// Joins migrations + seed into one file Rakib can paste into the Supabase SQL Editor.
// Usage: npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("../supabase/", import.meta.url).pathname;
const migrations = readdirSync(join(root, "migrations")).filter((f) => f.endsWith(".sql")).sort();
const parts = [
  "-- Generated by `npm run db:bundle`. Do not edit by hand.",
  "-- Paste the whole file into Supabase -> SQL Editor -> New query -> Run. Run it once on a new project.",
  ...migrations.map((f) => `\n-- >>> migrations/${f}\n${readFileSync(join(root, "migrations", f), "utf8")}`),
  `\n-- >>> seed.sql\n${readFileSync(join(root, "seed.sql"), "utf8")}`,
];
writeFileSync(join(root, "deploy", "setup.sql"), parts.join("\n"));
console.log(`wrote supabase/deploy/setup.sql (${migrations.length} migrations + seed)`);
